import{_ as l,a0 as o,w as r,s as g,ao as t,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux 中的“大內存頁”（hugepage）是個什麼？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中的“大內存頁”（hugepage）是個什麼？ | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中的“大內存頁”（hugepage）是個什麼？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中的“大內存頁”（hugepage）是個什麼？ | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171102 What is huge pages in Linux","title":"Linux 中的“大內存頁”（hugepage）是個什麼？","tag":"201803","desc":""},"relativePath":"201803/20171102 What is huge pages in Linux.md","filePath":"[post].md"}'),u={name:"201803/20171102 What is huge pages in Linux.md"};function d(h,s,c,k,m,b){const n=o("Link");return r(),g("div",null,[s[20]||(s[20]=t(`<h1 id="linux-中的-大內存頁-hugepage-是個什麼" tabindex="-1">Linux 中的“大內存頁”（hugepage）是個什麼？ <a class="header-anchor" href="#linux-中的-大內存頁-hugepage-是個什麼" aria-label="Permalink to “Linux 中的“大內存頁”（hugepage）是個什麼？”">​</a></h1><blockquote><p>學習 Linux 中的<ruby>大內存頁<rt>hugepage</rt></ruby>。理解什麼是“大內存頁”，如何進行配置，如何查看當前狀態以及如何禁用它。</p></blockquote><p><img src="https://a1.kerneltalks.com/wp-content/uploads/2017/11/hugepages-in-linux.png" alt="Huge Pages in Linux"></p><p>本文中我們會詳細介紹<ruby>大內存頁<rt>huge page</rt></ruby>，讓你能夠回答：Linux 中的“大內存頁”是什麼？在 RHEL6、RHEL7、Ubuntu 等 Linux 中，如何啓用/禁用“大內存頁”？如何查看“大內存頁”的當前值？</p><p>首先讓我們從“大內存頁”的基礎知識開始講起。</p><h3 id="linux-中的-大內存頁-是個什麼玩意" tabindex="-1">Linux 中的“大內存頁”是個什麼玩意？ <a class="header-anchor" href="#linux-中的-大內存頁-是個什麼玩意" aria-label="Permalink to “Linux 中的“大內存頁”是個什麼玩意？”">​</a></h3><p>“大內存頁”有助於 Linux 系統進行虛擬內存管理。顧名思義，除了標準的 4KB 大小的頁面外，它們還能幫助管理內存中的巨大的頁面。使用“大內存頁”，你最大可以定義 1GB 的頁面大小。</p><p>在系統啓動期間，你能用“大內存頁”為應用程序預留一部分內存。這部分內存，即被“大內存頁”佔用的這些存儲器永遠不會被交換出內存。它會一直保留其中，除非你修改了配置。這會極大地提高像 Oracle 資料庫這樣的需要海量內存的應用程序的性能。</p><h3 id="為什麼使用-大內存頁" tabindex="-1">為什麼使用“大內存頁”？ <a class="header-anchor" href="#為什麼使用-大內存頁" aria-label="Permalink to “為什麼使用“大內存頁”？”">​</a></h3><p>在虛擬內存管理中，內核維護一個將虛擬內存地址映射到物理地址的表，對於每個頁面操作，內核都需要加載相關的映射。如果你的內存頁很小，那麼你需要加載的頁就會很多，導致內核會加載更多的映射表。而這會降低性能。</p><p>使用“大內存頁”，意味着所需要的頁變少了。從而大大減少由內核加載的映射表的數量。這提高了內核級別的性能最終有利於應用程序的性能。</p><p>簡而言之，通過啓用“大內存頁”，系統具只需要處理較少的頁面映射表，從而減少訪問/維護它們的開銷！</p><h3 id="如何配置-大內存頁" tabindex="-1">如何配置“大內存頁”？ <a class="header-anchor" href="#如何配置-大內存頁" aria-label="Permalink to “如何配置“大內存頁”？”">​</a></h3><p>運行下面命令來查看當前“大內存頁”的詳細內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # grep Huge /proc/meminfo</span></span>
<span class="line"><span>AnonHugePages:         0 kB</span></span>
<span class="line"><span>HugePages_Total:       0</span></span>
<span class="line"><span>HugePages_Free:        0</span></span>
<span class="line"><span>HugePages_Rsvd:        0</span></span>
<span class="line"><span>HugePages_Surp:        0</span></span>
<span class="line"><span>Hugepagesize:       2048 kB</span></span></code></pre></div><p>從上面輸出可以看到，每個頁的大小為 2MB（<code>Hugepagesize</code>），並且系統中目前有 <code>0</code> 個“大內存頁”（<code>HugePages_Total</code>）。這裏“大內存頁”的大小可以從 <code>2MB</code> 增加到 <code>1GB</code>。</p><p>運行下面的腳本可以知道系統當前需要多少個巨大頁。該腳本取之於 Oracle。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># hugepages_settings.sh</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Linux bash script to compute values for the</span></span>
<span class="line"><span># recommended HugePages/HugeTLB configuration</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Note: This script does calculation for all shared memory</span></span>
<span class="line"><span># segments available when the script is run, no matter it</span></span>
<span class="line"><span># is an Oracle RDBMS shared memory segment or not.</span></span>
<span class="line"><span># Check for the kernel version</span></span>
<span class="line"><span>KERN=\`uname -r | awk -F. &#39;{ printf(&quot;%d.%d\\n&quot;,$1,$2); }&#39;\`</span></span>
<span class="line"><span># Find out the HugePage size</span></span>
<span class="line"><span>HPG_SZ=\`grep Hugepagesize /proc/meminfo | awk {&#39;print $2&#39;}\`</span></span>
<span class="line"><span># Start from 1 pages to be on the safe side and guarantee 1 free HugePage</span></span>
<span class="line"><span>NUM_PG=1</span></span>
<span class="line"><span># Cumulative number of pages required to handle the running shared memory segments</span></span>
<span class="line"><span>for SEG_BYTES in \`ipcs -m | awk {&#39;print $5&#39;} | grep &quot;[0-9][0-9]*&quot;\`</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>   MIN_PG=\`echo &quot;$SEG_BYTES/($HPG_SZ*1024)&quot; | bc -q\`</span></span>
<span class="line"><span>   if [ $MIN_PG -gt 0 ]; then</span></span>
<span class="line"><span>      NUM_PG=\`echo &quot;$NUM_PG+$MIN_PG+1&quot; | bc -q\`</span></span>
<span class="line"><span>   fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span># Finish with results</span></span>
<span class="line"><span>case $KERN in</span></span>
<span class="line"><span>   &#39;2.4&#39;) HUGETLB_POOL=\`echo &quot;$NUM_PG*$HPG_SZ/1024&quot; | bc -q\`;</span></span>
<span class="line"><span>          echo &quot;Recommended setting: vm.hugetlb_pool = $HUGETLB_POOL&quot; ;;</span></span>
<span class="line"><span>   &#39;2.6&#39; | &#39;3.8&#39; | &#39;3.10&#39; | &#39;4.1&#39; ) echo &quot;Recommended setting: vm.nr_hugepages = $NUM_PG&quot; ;;</span></span>
<span class="line"><span>    *) echo &quot;Unrecognized kernel version $KERN. Exiting.&quot; ;;</span></span>
<span class="line"><span>esac</span></span>
<span class="line"><span># End</span></span></code></pre></div><p>將它以 <code>hugepages_settings.sh</code> 為名保存到 <code>/tmp</code> 中，然後運行之：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # sh /tmp/hugepages_settings.sh</span></span>
<span class="line"><span>Recommended setting: vm.nr_hugepages = 124</span></span></code></pre></div><p>你的輸出類似如上結果，只是數字會有一些出入。</p><p>這意味着，你係統需要 124 個每個 2MB 的“大內存頁”！若你設置頁面大小為 4MB，則結果就變成了 62。你明白了吧？</p><h3 id="配置內核中的-大內存頁" tabindex="-1">配置內核中的“大內存頁” <a class="header-anchor" href="#配置內核中的-大內存頁" aria-label="Permalink to “配置內核中的“大內存頁””">​</a></h3>`,23)),i("p",null,[s[1]||(s[1]=a("本文最後一部分內容是配置上面提到的 ",-1)),e(n,{href:"https://kerneltalks.com/linux/how-to-tune-kernel-parameters-in-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("內核參數 ",-1)])]),_:1}),s[2]||(s[2]=a(" ，然後重新加載。將下面內容添加到 ",-1)),s[3]||(s[3]=i("code",null,"/etc/sysctl.conf",-1)),s[4]||(s[4]=a(" 中，然後輸入 ",-1)),s[5]||(s[5]=i("code",null,"sysctl -p",-1)),s[6]||(s[6]=a(" 命令重新加載配置。",-1))]),s[21]||(s[21]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vm.nr_hugepages=126</span></span></code></pre></div><p>注意我們這裏多加了兩個額外的頁，因為我們希望在實際需要的頁面數量之外多一些額外的空閒頁。</p><p>現在，內核已經配置好了，但是要讓應用能夠使用這些“大內存頁”還需要提高內存的使用閥值。新的內存閥值應該為 126 個頁 x 每個頁 2 MB = 252 MB，也就是 258048 KB。</p><p>你需要編輯 <code>/etc/security/limits.conf</code> 中的如下配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>soft memlock 258048</span></span>
<span class="line"><span>hard memlock 258048</span></span></code></pre></div><p>某些情況下，這些設置是在指定應用的文件中配置的，比如 Oracle DB 就是在 <code>/etc/security/limits.d/99-grid-oracle-limits.conf</code> 中配置的。</p><p>這就完成了！你可能還需要重啓應用來讓應用來使用這些新的巨大頁。</p><h3 id="如何禁用-大內存頁" tabindex="-1">如何禁用“大內存頁”？ <a class="header-anchor" href="#如何禁用-大內存頁" aria-label="Permalink to “如何禁用“大內存頁”？”">​</a></h3><p>“大內存頁”默認是開啓的。使用下面命令來查看“大內存頁”的當前狀態。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks# cat /sys/kernel/mm/transparent_hugepage/enabled</span></span>
<span class="line"><span>[always] madvise never</span></span></code></pre></div><p>輸出中的 <code>[always]</code> 標誌説明系統啓用了“大內存頁”。</p><p>若使用的是基於 RedHat 的系統，則應該要查看的文件路徑為 <code>/sys/kernel/mm/redhat_transparent_hugepage/enabled</code>。</p><p>若想禁用“大內存頁”，則在 <code>/etc/grub.conf</code> 中的 <code>kernel</code> 行後面加上 <code>transparent_hugepage=never</code>，然後重啓系統。</p><hr>`,14)),i("p",null,[s[8]||(s[8]=a("via: ",-1)),e(n,{href:"https://kerneltalks.com/services/what-is-huge-pages-in-linux/"},{default:p(()=>[...s[7]||(s[7]=[a("https://kerneltalks.com/services/what-is-huge-pages-in-linux/",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("作者：",-1)),e(n,{href:"https://kerneltalks.com"},{default:p(()=>[...s[9]||(s[9]=[a("Shrikant Lavhate",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const L=l(u,[["render",d]]);export{_ as __pageData,L as default};
